from taf.rfrl.procedures.resources.python.ssh_port_forwarder.SSHPortForwarder import SSHPortForwarder


def establish_ssh_tunnel(ssh_host, ssh_port, ssh_username, ssh_password, remote_host, remote_port,
                         local_host='localhost', local_port=2137):
    """
    Establish SSH tunnel to remote host and port via SSH server. The SSH server is used as a bridge to forward traffic
    from local port to remote host and port.
    :param ssh_host: SSH server address.
    :type ssh_host: str
    :param ssh_port: SSH server port.
    :type ssh_port: int
    :param ssh_username: SSH server username.
    :type ssh_username: str
    :param ssh_password: SSH server password.
    :type ssh_password: str
    :param remote_host: Remote host to forward traffic to.
    :type remote_host: str
    :param remote_port: Remote port to forward traffic to.
    :type remote_port: int
    :param local_host: Local host to forward traffic from. Default is 'localhost'.
    :type local_host: str
    :param local_port: Local port to forward traffic from. Default is 2137.
    :type local_port: int

    :return: SSH tunnel object.
    :rtype: SSHPortForwarder
    """
    ssh_tunnel = SSHPortForwarder(ssh_host, ssh_port, ssh_username, ssh_password)
    ssh_tunnel.setup_tunnel(remote_host=remote_host, remote_port=remote_port,
                            local_host=local_host, local_port=local_port)
    return ssh_tunnel
